class Registry<T> {
    private final List<T> items = new ArrayList<>();
    Registry<T> add(T t) { items.add(t); return this; }
    <R> List<R> mapAll(java.util.function.Function<? super T, ? extends R> f) {
        List<R> out = new ArrayList<>();
        for (T t : items) out.add(f.apply(t));
        return out;
    }
}
